"""Summarize revenue by region."""


def summarize(rows):
    """Aggregate total revenue per region.

    Args:
        rows: list of dicts, each with keys 'region' and 'revenue'.
              'revenue' may be a number or a numeric string.

    Returns:
        dict mapping region -> total revenue (float).
        Rows whose revenue is missing or unparseable are ignored.
    """
    totals = {}
    for row in rows:
        if not isinstance(row, dict):
            continue
        region = row.get('region')
        if region is None:
            continue
        raw = row.get('revenue')
        if raw is None:
            continue
        try:
            value = float(raw)
        except (TypeError, ValueError):
            continue
        totals[region] = totals.get(region, 0.0) + value
    return {region: float(total) for region, total in totals.items()}

